-- ============================================================
-- V5：题目解析润色（不改题面、答案与选项）
--
-- 背景：V2/V4 批量灌入的解析偏「标准答案腔」，部分只有一句话结论，
--      对错题复盘帮助有限。本脚本挑选 20 道高频错题，把 analysis
--      改写为带解题思路与易错点提醒的讲题口吻。
-- 注意：只做 UPDATE，不动表结构；题面（stem）、选项、答案保持原样。
-- ============================================================

-- ---------- 数据结构 ----------
UPDATE `question` SET `analysis` = '先分清删除和插入：删除第 i 个元素后，后面 n-i 个元素都要整体前移一位；插入才是移动 n-i+1 个。这两个公式最爱在选项里对调，做题时先问自己「动的是被删位置之后的元素，还是腾空位」。' WHERE `id` = 42;
UPDATE `question` SET `analysis` = '逐项排除最快：A、B、C 都是两种存储结构的典型性质；D 想一下单链表的结点里只有指向后继的 next 指针，走到尾结点后没有任何路回到头结点，除非从头再遍历一遍。凡是「链表反向访问」的选项，先默认它是错的再去验证。' WHERE `id` = 43;
UPDATE `question` SET `analysis` = '关键在于「能不能 O(1) 拿到前驱」。删除后继：p 的 next 就在那儿，改一个指针即可；删除 p 自己、在 p 前插入、找前驱，都得先从头遍历找前驱，都是 O(n)。做这类题先标出每个操作需要哪些结点，再看这些结点是否现成。' WHERE `id` = 44;
UPDATE `question` SET `analysis` = '栈和队列限制的只是「在哪里插入删除」：栈固定在栈顶、队列两端各管一头，但元素之间的逻辑关系仍然是一对一的线性关系，所以都是线性表。判断题里「受限」和「逻辑结构改变」是两码事，别混。' WHERE `id` = 45;
UPDATE `question` SET `analysis` = '循环队列的元素个数公式 (rear-front+M)%M 建议直接记结论，再用一个小例子验证：M=5，front=4，rear=1 时队列跨过数组末尾，(1-4+5)%5=2，正好是 4、0 两个元素。取模就是为了让减出负数时绕回一圈。' WHERE `id` = 46;
UPDATE `question` SET `analysis` = '易错点在 D 选项「4，3，1，2」：若 4 第一个出栈，说明 1、2、3 已经全部进栈压着，此后出栈只能按 3、2、1 的逆序进行，1 不可能先于 2 出来。判断出栈序列合法性，盯着「谁第一个出栈」往回推最省事。' WHERE `id` = 47;
UPDATE `question` SET `analysis` = '先序遍历口诀「根左右」。某结点没有左子树，访问完它自己之后，左子树这步等于空过，自然轮到右子树的根。容易误选「父结点」，那是中序/后序回到上层时的情形，别把遍历方向搞反。' WHERE `id` = 48;
UPDATE `question` SET `analysis` = '这个公式值得现场推一遍而不是死记：总结点 n0+n1+n2，总边数 = 结点数-1，而边数又等于 n1+2n2（度数之和），两式联立立得 n0=n2+1。推过一遍之后，考试时遇到变形题（如只有 n0 求 n2）也不会慌。' WHERE `id` = 49;
UPDATE `question` SET `analysis` = '按题目给的规定来：用右子树中「最小关键字」替补。先把树画出来：5 的右子树根是 8，而 8 没有左孩子，所以右子树的最小关键字就是 8 本身。易错点是习惯性地去找「中序后继的左下角」，这棵树里 8 已经是最左了，别画蛇添足。' WHERE `id` = 50;
UPDATE `question` SET `analysis` = '完全图是「每对顶点之间都恰有一条边」的图，边数就是从 n 个顶点里选 2 个的组合数 C(n,2)=n(n-1)/2。分母 2 是因为无向图的边不区分方向，这个 2 忘掉的话就会错选 n(n-1)。' WHERE `id` = 51;
UPDATE `question` SET `analysis` = '邻接矩阵的本质是「用数组下标直接对应两个顶点」，判断 (u,v) 有没有边就是看 A[u][v] 是 0 还是 1，一次下标访问，O(1)。对比记忆：邻接表要顺着边链表扫，最坏 O(度数)。两边的复杂度经常互为反例出题。' WHERE `id` = 52;
UPDATE `question` SET `analysis` = 'A、B、C 都是能严格论证的结论；D 错在「唯一」二字：同一个顶点出发，邻接点存储次序不同，DFS 访问序列就不同。凡是遍历序列类的选项出现「唯一」「一定」，先提高警惕，图和树的遍历大多不唯一。' WHERE `id` = 53;
UPDATE `question` SET `analysis` = '想通一件事就简单了：任何生成树都有且只有 n-1 条边。每条边统一加 c，每棵生成树的权值和都增加 (n-1)c，大家加的量一样，原来的大小关系不变，最小生成树还是同一棵，权值变成 T+(n-1)c。易错点是顺手写成 T+nc，把 n 条边当成了 n-1 条。' WHERE `id` = 54;
UPDATE `question` SET `analysis` = '稳定性记一组反例最牢：简单选择排序在「交换」时可能跨越相等元素，比如序列 5a、5b、2，第一趟 5a 和 2 交换后 5a 就跑到 5b 后面了。冒泡、直接插入、归并都是相邻或有序段内移动，能保住相对次序。' WHERE `id` = 55;
UPDATE `question` SET `analysis` = '直接插入排序的耗时取决于「逆序对有多少」。序列本身递增有序时，每个元素插入都只比较一次就到位，共 n-1 轮、零移动，整体 O(n)。这也是它适合「基本有序数据」的原因，和快排的最坏情形正好互补。' WHERE `id` = 56;
UPDATE `question` SET `analysis` = '先建堆再走一趟：大根堆的堆顶就是全序列最大值 97，堆排序第一趟把 97 和末尾元素交换，也就是把最大值沉到序列末尾。记住「一趟堆排序固定一个当前最大（小）值」，逐趟递推即可，不用真把整个堆画完。' WHERE `id` = 57;
UPDATE `question` SET `analysis` = '折半查找每比较一次，查找区间减半，n 个元素最多比较 ⌈log2(n+1)⌉ 次，平均下来就是 O(log n) 量级。注意前提是「顺序存储 + 有序」，两个条件缺一个折半查找都不成立，判断题里常挖这个坑。' WHERE `id` = 58;
UPDATE `question` SET `analysis` = '把探测过程一步步写出来就不会错：19%11=8 占 8 号；30%11=8 冲突，顺移到 9；41%11=8 又冲突，探测 8、9 都被占，最后落 10。线性探测的堆积效应要心里有数——冲突的元素会「赖」在别人的地址后面，影响后续所有探测。' WHERE `id` = 59;
UPDATE `question` SET `analysis` = '用 AVL 树最少结点递推式 N(h)=N(h-1)+N(h-2)+1（N(1)=1，N(2)=2）算出 N(5)=12、N(6)=20：15 个结点撑不起 6 层，但足够 5 层，所以树高最大为 5，查找最多比较 5 次。这类题必须动手递推，凭感觉估很容易差一层。' WHERE `id` = 60;

-- ---------- 计算机组成原理 ----------
UPDATE `question` SET `analysis` = '题问的是「计算机系统」这个最大概念：硬件 + 软件，缺一不可。B 之外的选项都只描述了硬件内部的一部分（主机、CPU、运算器控制器），层次低了。做概念题先看清主语的层级，再对号入座。' WHERE `id` = 61;
UPDATE `question` SET `analysis` = '冯·诺依曼思想的三个要点要能默写：五大部件、存储程序（程序和数据一样预先存入存储器）、二进制表示。本题只考五大部件这一点，判断为正确。后面若考「以运算器为中心」还是「以存储器为中心」，注意现代机器已经是后者。' WHERE `id` = 62;
